alter table public.alan_people add column if not exists photo_path text, add column if not exists identity_docs jsonb not null default '[]'::jsonb;
insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('alan-private-documents','alan-private-documents',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict (id) do update set public=false,file_size_limit=10485760,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists "alan_private_docs_insert_owner" on storage.objects;
create policy "alan_private_docs_insert_owner" on storage.objects for insert to authenticated with check (bucket_id='alan-private-documents' and array_length(storage.foldername(name),1)>=2 and exists(select 1 from public.alan_people p where p.id::text=(storage.foldername(name))[2] and p.owner_id::text=(storage.foldername(name))[1] and (p.owner_id=auth.uid() or (auth.jwt()->'app_metadata'->>'role')='superadmin')));
drop policy if exists "alan_private_docs_select_owner" on storage.objects;
create policy "alan_private_docs_select_owner" on storage.objects for select to authenticated using (bucket_id='alan-private-documents' and array_length(storage.foldername(name),1)>=2 and exists(select 1 from public.alan_people p where p.id::text=(storage.foldername(name))[2] and p.owner_id::text=(storage.foldername(name))[1] and (p.owner_id=auth.uid() or (auth.jwt()->'app_metadata'->>'role')='superadmin')));
drop policy if exists "alan_private_docs_delete_owner" on storage.objects;
create policy "alan_private_docs_delete_owner" on storage.objects for delete to authenticated using (bucket_id='alan-private-documents' and array_length(storage.foldername(name),1)>=2 and exists(select 1 from public.alan_people p where p.id::text=(storage.foldername(name))[2] and p.owner_id::text=(storage.foldername(name))[1] and (p.owner_id=auth.uid() or (auth.jwt()->'app_metadata'->>'role')='superadmin')));
